# ---------------------------------------------------------------------------
# Small helpers
# ---------------------------------------------------------------------------

def esc(value) -> str:
    """HTML-escape a value. Also neutralises '$' so Streamlit never treats it as LaTeX."""
    if value is None:
        return ""
    return html.escape(str(value)).replace("$", "&#36;")


def rich(text) -> str:
    """Escape text, then allow **bold** and keep line breaks."""
    out = esc(text)
    out = re.sub(r"\*\*(.+?)\*\*", r"<strong>\1</strong>", out)
    return out.replace("\n", "<br>")


def render(markup: str) -> None:
    """Flatten indentation/blank lines so Markdown never turns the HTML into a code block."""
    flat = " ".join(line.strip() for line in markup.strip().splitlines() if line.strip())
    st.markdown(flat, unsafe_allow_html=True)


def ui_button(label: str, icon: str = None, **kwargs):
    """st.button with a Material icon where the installed Streamlit supports it."""
    if icon:
        try:
            return st.button(label, icon=icon, **kwargs)
        except TypeError:
            pass
    return st.button(label, **kwargs)


def form_container():
    """A keyed container we can style as a card (falls back on older Streamlit)."""
    try:
        return st.container(key="formcard")
    except TypeError:
        return st.container()


def meter(pct: float, color: str) -> str:
    pct = max(0.0, min(1.0, pct))
    return f'<div class="meter"><span style="width:{pct * 100:.0f}%;background:{color}"></span></div>'


def initials(name: str) -> str:
    parts = [p for p in re.split(r"\s+", (name or "").strip()) if p]
    return ("".join(p[0] for p in parts[:2]) or "?").upper()


