# ---------------------------------------------------------------------------
# Session state + callbacks
# ---------------------------------------------------------------------------

_DEFAULTS = {
    "result": None, "history": [], "input_text": "",
    "emp_name": "", "emp_email": "",
    "notice": None, "error": None,
}
for _k, _v in _DEFAULTS.items():
    if _k not in st.session_state:
        st.session_state[_k] = _v


def run_request(text: str, name: str, email: str) -> None:
    name = (name or "").strip()
    email = (email or "").strip()
    st.session_state.notice = None
    try:
        result = orchestrator.process(user_input=text, employee_name=name, employee_email=email)
    except Exception as exc:  # keep the UI alive whatever the backend does
        st.session_state.result = None
        st.session_state.error = "The agent could not safely process this request. Please retry or provide more detail."
        return
    st.session_state.error = None
    st.session_state.result = result
    st.session_state.history.append(
        {"time": datetime.now().strftime("%H:%M:%S"), "input": text, "name": name, "email": email, "result": result}
    )


def on_submit() -> None:
    text = (st.session_state.input_text or "").strip()
    if not text:
        st.session_state.notice = "Describe the problem first, then select Process request."
        return
    run_request(text, st.session_state.emp_name, st.session_state.emp_email)


def on_demo(query: str, name: str, email: str) -> None:
    st.session_state.input_text = query
    st.session_state.emp_name = name
    st.session_state.emp_email = email
    run_request(query, name, email)


def on_clear() -> None:
    st.session_state.input_text = ""
    st.session_state.result = None
    st.session_state.notice = None
    st.session_state.error = None


def on_open(idx: int) -> None:
    item = st.session_state.history[idx]
    st.session_state.input_text = item["input"]
    st.session_state.emp_name = item["name"]
    st.session_state.emp_email = item["email"]
    st.session_state.result = item["result"]
    st.session_state.error = None
    st.session_state.notice = None


def request_for(result: dict):
    """Find the history entry that produced this result (matched by identity)."""
    for item in reversed(st.session_state.history):
        if item["result"] is result:
            return item
    return None


