def chip(ok: bool, label_ok: str, label_bad: str) -> str:
    if ok:
        return f'<span class="chip"><i></i>{esc(label_ok)}</span>'
    return f'<span class="chip bad"><i></i>{esc(label_bad)}</span>'


def render_topbar() -> None:
    p_ok = bool((validation.get("policies") or {}).get("valid"))
    t_ok = bool((validation.get("tickets") or {}).get("valid"))
    r_ok = bool((validation.get("requests") or {}).get("valid"))
    ticket_count = (validation.get("tickets") or {}).get("count", 0)
    chips = [
        '<span class="chip info"><i></i>Runs locally, no external API</span>',
        chip(p_ok, f"{len(all_policies)} policies", "Policies failed to load"),
        chip(t_ok, f"{ticket_count} past tickets", "Ticket history failed to load"),
        chip(r_ok, f"{len(all_requests)} employee requests", "Requests failed to load"),
        f'<span class="chip info"><i></i>{len(st.session_state.history)} handled this session</span>',
    ]
    render(
        f"""
        <div class="topbar">
            <div class="brand">
                <img class="brand-logo" src="data:image/png;base64,{VERIDIAN_LOGO_B64}" alt="Veridian — Smarter IT. Stronger Business." />
                <div class="brand-copy">
                    <div class="brand-name">IT service desk</div>
                    <div class="brand-sub">Internal support &amp; policy operations</div>
                </div>
            </div>
            <div class="chips">{''.join(chips)}</div>
        </div>
        """
    )


def render_scenario_grid(scenarios, key_prefix: str) -> None:
    cols = st.columns(4)
    for i, (label, query, emp, email, icon) in enumerate(scenarios):
        with cols[i % 4]:
            ui_button(label, icon=icon, key=f"{key_prefix}_{i}", use_container_width=True, on_click=on_demo, args=(query, emp, email))


def render_examples() -> None:
    render_scenario_grid(DEMO_SCENARIOS, "demo")


def render_eval_examples() -> None:
    render(
        '<div class="muted" style="margin-bottom:.9rem;">Harder cases for checking the agent: '
        "edge cases, policy conflicts, and requests that push for approval now and justification later.</div>"
    )
    render_scenario_grid(EVAL_SCENARIOS, "eval")


def render_input(compact: bool) -> None:
    if not compact:
        render(
            """
            <div class="hero">
                <div class="hero-title" role="heading" aria-level="1">Internal IT support,<br><span class="accent">grounded in policy.</span></div>
                <div class="hero-sub">Describe an employee issue in plain language. The local agent identifies the request type,
                retrieves the relevant Veridian policy, evaluates the case deterministically, and records the decision context.</div>
            </div>
            """
        )
    else:
        render('<div style="height:1.3rem"></div>')

    with form_container():
        st.text_area(
            "What's the problem?",
            key="input_text",
            placeholder="e.g. My VPN stopped working this morning. I'm locked out of my account. I need a monitor for my home office.",
            height=84 if compact else 118,
        )
        c_name, c_email, c_go, c_clear = st.columns([2.2, 2.6, 1.7, 0.9])
        with c_name:
            st.text_input("Your name", key="emp_name", placeholder="Your name")
        with c_email:
            st.text_input("Work email", key="emp_email", placeholder="you@company.example")
        with c_go:
            render('<div style="height:1.75rem"></div>')
            ui_button("Process request", icon=":material/send:", type="primary", use_container_width=True, on_click=on_submit)
        with c_clear:
            render('<div style="height:1.75rem"></div>')
            st.button("Clear", use_container_width=True, on_click=on_clear)

    if st.session_state.notice:
        st.warning(st.session_state.notice)
    if st.session_state.error:
        st.error(st.session_state.error)

    if compact:
        with st.expander("Try another example"):
            render_examples()
        with st.expander("Evaluator test scenarios (edge cases)"):
            render_eval_examples()
    else:
        render('<div class="examples-h">Not sure what to write? Start from an example.</div>')
        render_examples()
        with st.expander("Evaluator test scenarios (edge cases)"):
            render_eval_examples()


