# ---------------------------------------------------------------------------
# Result: outcome band
# ---------------------------------------------------------------------------

def fact(key: str, value_html: str, sub_html: str = "", cls: str = "", style: str = "") -> str:
    sub = f'<div class="fact-s">{sub_html}</div>' if sub_html else ""
    return f'<div class="fact"><div class="fact-k">{esc(key)}</div><div class="fact-v {cls}" style="{style}">{value_html}</div>{sub}</div>'


def render_verdict(ctx: dict) -> None:
    decision, meta, dec_key = ctx["decision"], ctx["meta"], ctx["dec_key"]
    risk = decision.get("risk_level")
    human_value = decision.get("requires_human")
    human = bool(human_value) if human_value is not None else None
    ticket = ctx["ticket"]

    segs = "".join(
        f'<div class="rail-seg{" on" if key == dec_key else ""}" style="--c:{DECISIONS[key]["color"]}">{label}</div>'
        for key, label in RAIL
    )
    facts = []
    if risk is not None:
        facts.append(fact("Risk", esc(risk), style=f"color:{RISK_COLORS.get(risk, 'var(--text)')}"))
    if human is not None:
        facts.append(fact("Human review", "Required" if human else "Not required",
                           style=f"color:{'var(--escalate)' if human else 'var(--resolve)'}"))
    if ctx["policy_id"]:
        facts.append(fact("Policy applied", esc(ctx["policy_id"]), ctx["policy_title"], cls="mono"))
    if ticket:
        ticket_id = ticket.get("ticket_id")
        if ticket_id:
            facts.append(fact("Ticket", esc(ticket_id), cls="mono"))
    if not facts:
        facts.append(fact("Case metadata", "Not specified in supplied data", style="color:var(--text3)"))
    if decision.get("route_to"):
        facts.append(fact("Route to", esc(decision["route_to"]), style="color:var(--route)"))

    reason = decision.get("reason")
    why = f'<div class="verdict-why">{rich(reason)}</div>' if reason else ""

    flags = []
    if ctx["low_conf"]:
        bits = []
        if ctx["conf"] < LOW_CONF:
            bits.append(f"request type {ctx['conf']:.0%}")
        if ctx["policy_id"] and ctx["sim"] < LOW_CONF:
            bits.append(f"policy match {ctx['sim']:.0%}")
        flags.append(
            '<div class="flag"><span class="signal-dot"></span><span><b>Low confidence</b> (' + ", ".join(bits) + "). "
            "Treat this outcome as a suggestion and have the IT team confirm it.</span></div>"
        )
    for e in ctx["errors"]:
        flags.append(f'<div class="flag bad"><span>!</span><span><b>Agent error.</b> {esc(e.get("detail", ""))}</span></div>')

    render(
        f"""
        <div class="verdict" style="--dc:{meta['color']}">
            <div class="verdict-top">
                <div>
                    <div class="verdict-k">Outcome</div>
                    <div class="verdict-word">{esc(meta['label'])}</div>
                    {why}
                </div>
                <div>
                    <div class="rail">{segs}</div>
                    <div class="rail-cap">{esc(meta['blurb'])}</div>
                </div>
            </div>
            <div class="facts">{''.join(facts)}</div>
            {''.join(flags)}
        </div>
        """
    )


# ---------------------------------------------------------------------------
# Result: reply + ticket
# ---------------------------------------------------------------------------

def draft_reply(ctx: dict) -> str:
    """Plain-text reply an IT agent could paste into email or chat."""
    decision, ticket, item = ctx["decision"], ctx["ticket"] or {}, ctx["item"]
    first = ((item or {}).get("name") or "there").split()[0]
    body = re.sub(r"\*\*(.+?)\*\*", r"\1", str(ctx["result"].get("response", "")))
    lines = [f"Hi {first},", "", body.strip()]
    if decision.get("next_action"):
        lines += ["", f"Next step: {decision['next_action']}"]
    if ticket.get("ticket_id"):
        lines += ["", f"Ticket reference: {ticket['ticket_id']}"]
    lines += ["", "Veridian IT Service Desk"]
    return "\n".join(lines)


def render_ticket(ticket) -> None:
    if not ticket:
        render(
            """
            <div class="notick"><b>No ticket returned</b>
            The backend did not return a current ticket for this request.</div>
            """
        )
        return

    fields = []
    for key, label in (
        ("ticket_id", "Ticket"),
        ("status", "Status"),
        ("employee", "Employee"),
        ("policy_id", "Policy"),
        ("created_at", "Created"),
    ):
        value = ticket.get(key)
        if value not in (None, ""):
            fields.append(
                f'<div class="kk">{esc(label)}</div><div class="vv">{esc(value)}</div>'
            )

    if not fields:
        fields.append(
            '<div class="kk">Case</div><div class="vv">Ticket returned without display metadata.</div>'
        )

    ticket_id = ticket.get("ticket_id")
    title = esc(ticket_id) if ticket_id else "Current ticket"
    render(
        f"""
        <div class="stub">
            <div class="stub-top">
                <div class="stub-k">CURRENT CASE</div>
                <div class="stub-id">{title}</div>
            </div>
            <div class="stub-perf"></div>
            <div class="stub-bottom">
                <div class="kv">{''.join(fields)}</div>
            </div>
        </div>
        """
    )


def render_reply(ctx: dict) -> None:
    item, meta, decision = ctx["item"], ctx["meta"], ctx["decision"]
    next_action = decision.get("next_action")
    next_html = (
        f'<div class="nextaction"><div class="na-k">Next step for the employee</div><div class="na-v">{rich(next_action)}</div></div>'
        if next_action else ""
    )
    asked = ""
    if item:
        asked = (
            f'<div class="msg"><div class="avatar">{esc(initials(item["name"]))}</div>'
            f'<div class="bubble"><div class="who"><b>{esc(item["name"])}</b> · {esc(item["time"])}</div>'
            f'<div class="say">{rich(item["input"])}</div></div></div>'
        )

    left, right = st.columns([1.7, 1], gap="large")
    with left:
        render(
            f"""
            <div class="section-h">Reply to the employee</div>
            <div class="section-sub">What the agent sent back.</div>
            <div class="chat" style="--dc:{meta['color']}">
                {asked}
                <div class="msg">
                    <div class="avatar bot">V</div>
                    <div class="bubble bot">
                        <div class="who"><b>Veridian agent</b></div>
                        <div class="say">{rich(ctx['result'].get('response', ''))}</div>
                    </div>
                </div>
            </div>
            <div style="--dc:{meta['color']}">{next_html}</div>
            """
        )
        with st.expander("Copy a reply to the employee"):
            st.code(draft_reply(ctx), language=None)
    with right:
        render('<div class="section-h">Ticket</div><div class="section-sub">Opened only when the policy calls for it.</div>')
        render_ticket(ctx["ticket"])


# ---------------------------------------------------------------------------
# Result: the six-step walkthrough
# ---------------------------------------------------------------------------

def log_html(entries: list) -> str:
    if not entries:
        return ""
    rows = []
    for e in entries:
        event = e.get("event", "")
        label = TRACE_LABELS.get(event, event.replace("_", " ").capitalize())
        rows.append(
            f'<div class="log-row{" err" if event == "ERROR" else ""}"><span class="lt">{esc(e.get("timestamp", ""))}</span>'
            f'<span class="ln">{esc(label)}</span><span class="ld">{esc(e.get("detail", ""))}</span></div>'
        )
    return f'<div class="stage-log">{"".join(rows)}</div>'


def stage_html(n: int, badge: tuple, evidence: str, entries: list) -> str:
    title, what = STAGES[n]
    text, cls = badge
    return (
        f'<div class="stage {cls if cls != "ok" else ""}">'
        f'<div class="stage-rail"><div class="pn">{n}</div></div>'
        f'<div class="stage-body"><div class="stage-card">'
        f'<div class="stage-head"><div class="stage-title">{esc(title)}</div><span class="sbadge {cls}">{esc(text)}</span></div>'
        f'<div class="stage-what">{esc(what)}</div>'
        f'<div class="stage-ev">{evidence}</div>'
        f'{log_html(entries)}'
        f'</div></div></div>'
    )


def stage_evidence(ctx: dict) -> dict:
    intent, policy, decision, ticket = ctx["intent"], ctx["policy"], ctx["decision"], ctx["ticket"]
    item, meta = ctx["item"], ctx["meta"]
    conf, sim = ctx["conf"], ctx["sim"]
    out = {}

    # 1 Receive
    text = item["input"] if item else ""
    who = (
        f'<div class="meta-row"><span><b>From</b> {esc(item["name"])}</span><span><b>Email</b> {esc(item["email"])}</span>'
        f'<span><b>Received</b> {esc(item["time"])}</span></div>'
        if item else ""
    )
    out[1] = (f'<div class="quote">{rich(text)}</div>{who}', ("Done", "ok"))

    # 2 Understand
    label = str(intent.get("intent", "unknown")).replace("_", " ").capitalize()
    conf_color = "var(--resolve)" if conf >= 0.5 else ("var(--followup)" if conf >= LOW_CONF else "var(--escalate)")
    terms = "".join(f'<span class="term">{esc(t)}</span>' for t in (intent.get("matched_terms") or [])[:8])
    note = ""
    badge2 = ("Done", "ok")
    if conf < LOW_CONF:
        note = '<div class="ev-sub" style="color:var(--followup);margin-top:.7rem;">The agent is not sure it understood this. Read the label as a best guess.</div>'
        badge2 = ("Low confidence", "warn")
    out[2] = (
        f'<div class="ev-row"><div><div class="ev-k">Request type</div><div class="ev-big">{esc(label)}</div>'
        f'{meter(conf, conf_color)}<div class="ev-sub"><span style="color:{conf_color};font-weight:600;">{conf:.0%}</span> confident</div>{note}</div>'
        f'<div><div class="ev-k">Words that led to this</div>{terms or "<span class=muted>None recorded</span>"}</div></div>',
        badge2,
    )

    # 3 Match a policy
    pid = ctx["policy_id"]
    if not pid:
        out[3] = ('<div class="ev-sub">No policy in the Veridian knowledge base covers this request.</div>', ("No match", "warn"))
    else:
        full = retrieve_policy_by_id(pid)
        sim_color = "var(--resolve)" if sim >= 0.5 else ("var(--followup)" if sim >= LOW_CONF else "var(--escalate)")
        body = ""
        if full:
            body = f'<div class="policy-body">{rich(full.get("policy"))}</div><div class="policy-src">Source: {esc(full.get("source", "Veridian knowledge base"))}</div>'
            if pid == "KB-03":
                asset = retrieve_policy_by_id("ASSET-MGMT")
                if asset:
                    body += (
                        '<div class="conflict">A second policy also applies, and the two may conflict. A person needs to review this request.</div>'
                        f'<div class="ev-k" style="margin-top:.9rem;">{esc(asset.get("policy_id"))} · {esc(asset.get("title"))}</div>'
                        f'<div class="policy-body" style="--pc:var(--followup);margin-top:0;">{rich(asset.get("policy"))}</div>'
                        f'<div class="policy-src">Source: {esc(asset.get("source", "Veridian knowledge base"))}</div>'
                    )
        else:
            body = f'<div class="ev-sub">Policy {esc(pid)} could not be found in the knowledge base.</div>'
        weak = sim < LOW_CONF
        out[3] = (
            f'<div class="ev-row"><div><div class="ev-k">Best matching policy</div><div class="ev-big mono">{esc(pid)}</div>'
            f'<div class="ev-sub">{esc(ctx["policy_title"])}</div>{meter(sim, sim_color)}'
            f'<div class="ev-sub"><span style="color:{sim_color};font-weight:600;">{sim:.0%}</span> match</div></div>'
            f'<div><div class="ev-k">What the policy says</div>{body}</div></div>',
            ("Weak match", "warn") if weak else ("Done", "ok"),
        )

    # 4 Past tickets
    related = ctx["related"]
    if related:
        rows = []
        for t in related[:4]:
            summary = t.get("issue_summary", t.get("summary", ""))
            tag = '<span class="tag">Historical</span>' if t.get("source", "historical") == "historical" else ""
            rows.append(
                f'<div class="rel"><span class="rel-id">{esc(t.get("ticket_id"))}</span>{tag}'
                f'<div class="rel-sum">{esc(summary)}</div><div class="rel-st">{esc(t.get("status"))}</div></div>'
            )
        out[4] = ("".join(rows), ("Done", "ok"))
    else:
        out[4] = ('<div class="ev-sub">No similar past tickets found, so this looks like a new kind of issue.</div>', ("Done", "ok"))

    # 5 Decide
    risk = decision.get("risk_level")
    human_value = decision.get("requires_human")
    human = bool(human_value) if human_value is not None else None
    reason = decision.get("reason")
    route = decision.get("route_to")
    decision_meta = []
    if risk is not None:
        decision_meta.append(f'<span><b>Risk</b> <span style="color:{RISK_COLORS.get(risk, "var(--text)")};font-weight:600;">{esc(risk)}</span></span>')
    if human is not None:
        decision_meta.append(f'<span><b>Human review</b> {"Required" if human else "Not required"}</span>')
    if route:
        decision_meta.append(f'<span><b>Route to</b> {esc(route)}</span>')
    meta_html = ''.join(decision_meta) or '<span>Additional decision metadata not specified.</span>'
    out[5] = (
        f'<div class="ev-row"><div><div class="ev-k">Outcome</div><span class="dpill" style="--dc:{meta["color"]}">{esc(meta["label"])}</span>'
        f'<div class="meta-row">{meta_html}</div></div><div><div class="ev-k">Why</div><div class="ev-sub" style="margin-top:0;color:var(--text);">{rich(reason) if reason else "No reason recorded."}</div></div></div>',
        ("Human review", "warn") if human is True else ("Done", "ok"),
    )

    # 6 Act
    if ticket:
        act = (
            f'<div class="ev-sub" style="margin-top:0;color:var(--text);">Opened ticket <span class="rel-id">{esc(ticket.get("ticket_id"))}</span>. '
            'A reply was written for the employee.</div>'
        )
    else:
        act = '<div class="ev-sub" style="margin-top:0;color:var(--text);">No ticket was needed. A reply was written for the employee.</div>'
    out[6] = (act, ("Done", "ok"))
    return out


def render_walkthrough(ctx: dict) -> None:
    render(
        '<div class="section-h" style="margin-top:2.2rem;">How the agent worked this out</div>'
        '<div class="section-sub">The same six steps ran for this request. Each card shows what the step does, what it found, '
        "and the log lines it wrote.</div>"
    )
    by_stage = {n: [] for n in STAGES}
    for e in ctx["audit"]:
        by_stage[STAGE_OF_EVENT.get(e.get("event", ""), 6)].append(e)

    ev = stage_evidence(ctx)
    render("".join(stage_html(n, ev[n][1], ev[n][0], by_stage[n]) for n in STAGES))


def render_result(result: dict) -> None:
    intent = result.get("intent") or {}
    policy = result.get("policy") or {}
    decision = result.get("decision") or {}
    audit = result.get("audit") or []
    dec_key = decision.get("decision", "")
    conf = float(intent.get("confidence", 0.0) or 0.0)
    sim = float(policy.get("similarity", 0.0) or 0.0)
    policy_id = decision.get("policy_id") or policy.get("policy_id")
    policy_title = policy.get("title", "") if policy.get("policy_id") == policy_id else ""
    if policy_id and not policy_title:
        full = retrieve_policy_by_id(policy_id)
        policy_title = (full or {}).get("title", "")

    ctx = {
        "result": result, "intent": intent, "policy": policy, "decision": decision,
        "ticket": result.get("ticket"), "related": result.get("related_tickets") or [], "audit": audit,
        "item": request_for(result), "dec_key": dec_key, "conf": conf, "sim": sim,
        "policy_id": policy_id, "policy_title": policy_title,
        "low_conf": conf < LOW_CONF or bool(policy_id and sim < LOW_CONF),
        "errors": [e for e in audit if e.get("event") == "ERROR"],
        "meta": DECISIONS.get(
            dec_key,
            {"label": str(dec_key).replace("_", " ").capitalize() or "No decision", "color": "#a6bbb8", "blurb": "The agent did not reach a decision."},
        ),
    }

    st.write("")
    render_verdict(ctx)
    render(
        '<div class="section-h">Why this decision?</div>'
        '<div class="section-sub">Structured evidence produced by the backend. Private chain-of-thought is not displayed.</div>'
        f'<div class="evidence-chain">'
        f'<div class="evidence-step"><div class="evidence-no">01</div><div class="evidence-title">INTENT</div><div class="evidence-value">{esc(str(intent.get("intent") or "Not specified").replace("_", " ").title())}</div></div>'
        f'<div class="evidence-step"><div class="evidence-no">02</div><div class="evidence-title">POLICY</div><div class="evidence-value">{esc(policy_id or "Not specified")}</div></div>'
        f'<div class="evidence-step"><div class="evidence-no">03</div><div class="evidence-title">CONTEXT</div><div class="evidence-value">Historical tickets checked</div></div>'
        f'<div class="evidence-step"><div class="evidence-no">04</div><div class="evidence-title">EVALUATION</div><div class="evidence-value">{esc(decision.get("reason") or "Structured rule evaluation recorded")}</div></div>'
        f'<div class="evidence-step"><div class="evidence-no">05</div><div class="evidence-title">ACTION</div><div class="evidence-value">{esc(dec_key or "Not specified")}</div></div>'
        f'</div>'
    )
    st.write("")
    render_reply(ctx)
    render_walkthrough(ctx)


# ---------------------------------------------------------------------------
# Bottom tabs: audit, session tickets, history, knowledge base
# ---------------------------------------------------------------------------

def render_tabs(result) -> None:
    st.write("")
    tab_audit, tab_tickets, tab_hist, tab_kb = st.tabs(["Audit trail", "Session tickets", "Session history", "Knowledge base"])

    with tab_audit:
        if not result:
            render('<div class="muted">Process a request to see its audit trail.</div>')
        else:
            audit_text = format_trail(result.get("audit") or [])
            audit_text = audit_text if isinstance(audit_text, str) else str(audit_text)
            render(f'<div class="audit">{esc(audit_text).replace(chr(10), "<br>")}</div>')
            st.write("")
            tid = (result.get("ticket") or {}).get("ticket_id", "case")
            d1, d2, _ = st.columns([1.3, 1.3, 3])
            with d1:
                st.download_button("Download audit log", data=audit_text, file_name=f"audit-{tid}.txt", mime="text/plain", use_container_width=True)
            with d2:
                st.download_button("Export case (JSON)", data=json.dumps(result, indent=2, default=str), file_name=f"case-{tid}.json", mime="application/json", use_container_width=True)

    with tab_tickets:
        tickets = ticket_manager.get_session_tickets()
        if not tickets:
            render('<div class="muted">No tickets have been created in this session yet.</div>')
        else:
            rows = []
            for t in reversed(tickets):
                metadata = [str(t.get(k)) for k in ("status", "employee", "created_at") if t.get(k) not in (None, "")]
                rows.append(
                    f'<div class="rel"><span class="rel-id">{esc(t.get("ticket_id") or "Ticket")}</span>'
                    f'<div class="rel-sum">{esc(str(t.get("summary", ""))[:120])}</div>'
                    f'<div class="rel-st">{esc(" · ".join(metadata))}</div></div>'
                )
            render("".join(rows))

    with tab_hist:
        hist = st.session_state.history
        if not hist:
            render('<div class="muted">Requests you process appear here. Select Open to reload one.</div>')
        else:
            counts = {}
            for h in hist:
                k = ((h["result"] or {}).get("decision") or {}).get("decision", "")
                counts[k] = counts.get(k, 0) + 1
            tally = "".join(
                f'<span class="chip"><i style="background:{DECISIONS.get(k, {"color": "#a6bbb8"})["color"]}"></i>'
                f'<b>{n}</b> {esc(DECISIONS.get(k, {"label": k or "No decision"})["label"])}</span>'
                for k, n in counts.items()
            )
            render(f'<div class="tally">{tally}</div>')
            for idx in range(len(hist) - 1, -1, -1):
                item = hist[idx]
                dk = ((item["result"] or {}).get("decision") or {}).get("decision", "")
                m = DECISIONS.get(dk, {"label": dk or "No decision", "color": "#a6bbb8"})
                c1, c2 = st.columns([6, 1])
                with c1:
                    render(
                        f'<div class="hrow"><span class="hdot" style="background:{m["color"]}"></span>'
                        f'<div><div class="hrow-t">{esc(item["input"][:110])}</div>'
                        f'<div class="hrow-s">{esc(m["label"])} · {esc(item["name"])} · {esc(item["time"])}</div></div></div>'
                    )
                with c2:
                    st.button("Open", key=f"open_{idx}", use_container_width=True, on_click=on_open, args=(idx,))

    with tab_kb:
        if not all_policies:
            render('<div class="muted">No policies were loaded.</div>')
        for p in all_policies:
            with st.expander(f'{p.get("policy_id", "")} — {p.get("title", "")}'):
                render(
                    f'<div class="policy-body" style="margin-top:0;">{rich(p.get("policy"))}</div>'
                    f'<div class="policy-src">Source: {esc(p.get("source", "Veridian knowledge base"))}</div>'
                )


